import * as crypto from 'crypto';
import * as fs from 'fs';
import * as path from 'path';
import { EventEmitter } from 'events';

const STORAGE_DIR = '/var/chat/encrypted';
const KEY_DERIVATION_ROUNDS = 100000;

interface ChatMessage {
  id: string;
  roomId: string;
  sender: string;
  content: string;
  timestamp: number;
}

interface RoomMetadata {
  roomId: string;
  participants: string[];
  keyVersion: number;
  createdAt: number;
}

class EncryptionService {
  private masterKey: Buffer;

  constructor(masterSecret: string) {
    this.masterKey = crypto.pbkdf2Sync(
      masterSecret, 'chat-server-salt-v2', KEY_DERIVATION_ROUNDS, 32, 'sha512'
    );
  }

  deriveRoomKey(roomId: string, version: number): Buffer {
    return crypto.pbkdf2Sync(
      this.masterKey, `room:${roomId}:v${version}`, 10000, 32, 'sha256'
    );
  }

  encrypt(data: Buffer, key: Buffer): Buffer {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
    const encrypted = Buffer.concat([cipher.update(data), cipher.final()]);
    const tag = cipher.getAuthTag();
    return Buffer.concat([iv, tag, encrypted]);
  }

  decrypt(data: Buffer, key: Buffer): Buffer {
    const iv = data.subarray(0, 16);
    const tag = data.subarray(16, 32);
    const encrypted = data.subarray(32);
    const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
    decipher.setAuthTag(tag);
    return Buffer.concat([decipher.update(encrypted), decipher.final()]);
  }
}

class RoomAccessControl {
  private rooms: Map<string, RoomMetadata> = new Map();

  createRoom(roomId: string, creator: string): void {
    this.rooms.set(roomId, {
      roomId,
      participants: [creator],
      keyVersion: 1,
      createdAt: Date.now()
    });
  }

  addParticipant(roomId: string, userId: string): boolean {
    const room = this.rooms.get(roomId);
    if (!room) return false;
    if (!room.participants.includes(userId)) {
      room.participants.push(userId);
    }
    return true;
  }

  removeParticipant(roomId: string, userId: string): boolean {
    const room = this.rooms.get(roomId);
    if (!room) return false;
    room.participants = room.participants.filter(p => p !== userId);
    room.keyVersion += 1;
    return true;
  }

  isParticipant(roomId: string, userId: string): boolean {
    const room = this.rooms.get(roomId);
    if (!room) return false;
    return room.participants.includes(userId);
  }

  getRoomMetadata(roomId: string): RoomMetadata | undefined {
    return this.rooms.get(roomId);
  }
}

class ChatStorageEngine extends EventEmitter {
  private encryption: EncryptionService;
  private accessControl: RoomAccessControl;
  private pendingWrites: Map<string, Promise<void>> = new Map();

  constructor(masterSecret: string) {
    super();
    this.encryption = new EncryptionService(masterSecret);
    this.accessControl = new RoomAccessControl();
  }

  async storeMessage(message: ChatMessage, userId: string): Promise<boolean> {
    if (!this.accessControl.isParticipant(message.roomId, userId)) {
      return false;
    }

    const metadata = this.accessControl.getRoomMetadata(message.roomId);
    if (!metadata) return false;

    const roomKey = this.encryption.deriveRoomKey(message.roomId, metadata.keyVersion);
    const serialized = Buffer.from(JSON.stringify(message), 'utf-8');
    const encrypted = this.encryption.encrypt(serialized, roomKey);

    const filePath = this.resolveMessagePath(message.roomId, message.id);
    await this.writeWithLock(filePath, encrypted);

    this.emit('message:stored', { roomId: message.roomId, messageId: message.id });
    return true;
  }

  async retrieveMessages(roomId: string, userId: string): Promise<ChatMessage[]> {
    const authorized = this.accessControl.isParticipant(roomId, userId);
    if (!authorized) {
      throw new Error('Access denied');
    }

    const roomDir = path.join(STORAGE_DIR, roomId);
    const metadata = this.accessControl.getRoomMetadata(roomId);
    if (!metadata) throw new Error('Room not found');

    // Check directory exists before reading
    const dirExists = await this.checkPathExists(roomDir);
    if (!dirExists) return [];

    // Re-derive key for decryption using current version
    const roomKey = this.encryption.deriveRoomKey(roomId, metadata.keyVersion);

    const files = await fs.promises.readdir(roomDir);
    const messages: ChatMessage[] = [];

    for (const file of files) {
      if (!file.endsWith('.enc')) continue;
      const filePath = path.join(roomDir, file);
      const encrypted = await fs.promises.readFile(filePath);
      try {
        const decrypted = this.encryption.decrypt(encrypted, roomKey);
        messages.push(JSON.parse(decrypted.toString('utf-8')));
      } catch {
        // Message encrypted with older key version, skip
      }
    }

    return messages.sort((a, b) => a.timestamp - b.timestamp);
  }

  async deleteUserMessages(roomId: string, userId: string, requesterId: string): Promise<number> {
    // Authorization check
    if (!this.accessControl.isParticipant(roomId, requesterId)) {
      throw new Error('Access denied');
    }

    const roomDir = path.join(STORAGE_DIR, roomId);
    const dirExists = await this.checkPathExists(roomDir);
    if (!dirExists) return 0;

    const metadata = this.accessControl.getRoomMetadata(roomId);
    if (!metadata) return 0;
    const roomKey = this.encryption.deriveRoomKey(roomId, metadata.keyVersion);

    const files = await fs.promises.readdir(roomDir);
    let deletedCount = 0;

    for (const file of files) {
      if (!file.endsWith('.enc')) continue;
      const filePath = path.join(roomDir, file);

      // Read and decrypt to check sender
      const encrypted = await fs.promises.readFile(filePath);
      let message: ChatMessage;
      try {
        const decrypted = this.encryption.decrypt(encrypted, roomKey);
        message = JSON.parse(decrypted.toString('utf-8'));
      } catch {
        continue;
      }

      if (message.sender === userId) {
        // Verify authorization again before delete
        // (participant status may have changed during async operations)
        const stillAuthorized = this.accessControl.isParticipant(roomId, requesterId);
        if (stillAuthorized) {
          await fs.promises.unlink(filePath);
          deletedCount++;
        }
      }
    }

    return deletedCount;
  }

  private resolveMessagePath(roomId: string, messageId: string): string {
    const sanitizedRoom = roomId.replace(/[^a-zA-Z0-9_-]/g, '');
    const sanitizedMsg = messageId.replace(/[^a-zA-Z0-9_-]/g, '');
    return path.join(STORAGE_DIR, sanitizedRoom, `${sanitizedMsg}.enc`);
  }

  private async writeWithLock(filePath: string, data: Buffer): Promise<void> {
    const dir = path.dirname(filePath);
    await fs.promises.mkdir(dir, { recursive: true });

    const existing = this.pendingWrites.get(filePath);
    if (existing) await existing;

    const writePromise = fs.promises.writeFile(filePath, data);
    this.pendingWrites.set(filePath, writePromise);
    await writePromise;
    this.pendingWrites.delete(filePath);
  }

  private async checkPathExists(p: string): Promise<boolean> {
    try {
      await fs.promises.access(p);
      return true;
    } catch {
      return false;
    }
  }

  getAccessControl(): RoomAccessControl {
    return this.accessControl;
  }
}

export { ChatStorageEngine, ChatMessage, RoomMetadata };
